mapper.update:
UPDATE cut_approval_notification
SET status_code = #{query.newStatusCode},
    message_id = #{query.messageId},
    retry_count = #{query.retryCount},
    next_retry_at = #{query.nextRetryAt},
    last_error_code = #{query.lastErrorCode},
    sent_at = #{query.sentAt},
    version = #{query.expectedVersion} + 1,
    updater = #{query.updater},
    update_time = #{query.updateTime}
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.notificationId}
  AND channel_code = 'IN_PLATFORM'
  AND status_code = #{query.expectedStatusCode}
  AND version = #{query.expectedVersion}
  AND deleted = b'0'

UPDATE cut_approval_notification
SET status_code = #{query.newStatusCode},
    provider_reference_id = #{query.providerReferenceId},
    retry_count = #{query.retryCount},
    next_retry_at = #{query.nextRetryAt},
    last_error_code = #{query.lastErrorCode},
    last_attempt_at = #{query.lastAttemptAt},
    version = #{query.expectedVersion} + 1,
    updater = #{query.updater},
    update_time = #{query.updateTime}
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.notificationId}
  AND channel_code = #{query.channelCode}
  AND channel_code IN ('SMS','EMAIL','DINGTALK')
  AND status_code = #{query.expectedStatusCode}
  AND version = #{query.expectedVersion}
  AND deleted = b'0'
